mapper.select:
SELECT 
FROM article a

    JOIN article_tag t ON t.article_id = a.id AND t.tag_id = #{tagId}

WHERE a.status = 'PUBLISHED' AND a.deleted = 0
AND a.category_id = #{categoryId}
ORDER BY a.publish_time DESC, a.id DESC

SELECT a.id, a.author_id, a.publish_time FROM follow f JOIN article a ON a.author_id = f.followee_id WHERE f.follower_id = #{userId} AND f.status = 1 AND a.status = 'PUBLISHED' AND a.deleted = 0
AND f.followee_id NOT IN #{id}
ORDER BY a.publish_time DESC LIMIT #{limit}

SELECT id, author_id, publish_time
FROM article
WHERE status = 'PUBLISHED' AND deleted = 0 AND publish_time >= #{since}
